from context import *
folder=O/'public-client-check';folder.mkdir(exist_ok=True)
refs=''.join('<Reference Include="'+p.stem+'"><HintPath>'+str(p)+'</HintPath></Reference>'for p in(O/'installer-qa/launcher').glob('*.dll'))
(folder/'QA.csproj').write_text('<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net8.0-windows</TargetFramework><UseWPF>true</UseWPF><ImplicitUsings>enable</ImplicitUsings></PropertyGroup><ItemGroup><Using Include="System.IO" />'+refs+'</ItemGroup></Project>')
write(folder/'before.json',verify(read(P/'source/feed/v3/beta.json'),key()))
(folder/'Program.cs').write_text(r'''using System.Text.Json;using PawsPatchLauncher;
var root=args[0];var opt=new JsonSerializerOptions{PropertyNameCaseInsensitive=true};var cfg=JsonSerializer.Deserialize<LauncherConfiguration>(File.ReadAllText(args[1]),opt)!;cfg.CacheRoot=Path.Combine(root,"cache");var c=new FeedClient(cfg);var f=await c.GetChannelAsync("beta")??throw new Exception("Missing public feed");var version=f.Packages.Single(p=>p.Id=="pawpatch-core").Version;
if(version!="0.6.0-beta.2"){Console.WriteLine("PUBLIC_CLIENT_PENDING "+version);return;}
var settings=new UserSettings{Mod=GameMod.ArcaneWars,Channel="beta",GameTextLanguage="en",RussianLocalization=false,GameVoiceLanguage="en",CustomPlayerColors=true,DesyncMode="continue"};settings=EffectiveSettings.ForFeed(settings,f);var selected=GamePackageSelector.Select(f,settings,false,true);var before=JsonSerializer.Deserialize<ChannelManifest>(File.ReadAllText(Path.Combine(root,"before.json")),opt)!;var old=GamePackageSelector.Select(before,settings,false,true);var state=new InstallState{AppliedSettings=settings,Modules=old.ToDictionary(p=>p.Id,p=>new InstalledModule{Enabled=true,Version=p.Version,ArchiveSha256=p.Sha256,Priority=p.Priority})};if(!UpdateDetector.HasRemoteUpdate(state,selected,_=>false)||!UpdateDetector.HasModuleChanges(state,selected)||selected.Count(p=>p.Id.StartsWith("arcane-biome-textures-"))!=4)throw new Exception("No update or missing texture dependencies");
File.WriteAllText(Path.Combine(root,"result.json"),JsonSerializer.Serialize(new{passed=true,version,source=cfg.BetaFeedUrls,updateOffered=true,textureParts=4,executable=GameExecutableSelector.Select(cfg,settings,f),launcher=typeof(ModuleInstaller).Assembly.GetName().Version!.ToString()}));Console.WriteLine("PUBLIC_CLIENT_UPDATE_PASS "+version);
''')
print(run([SDK,'run','--project',folder/'QA.csproj','-c','Release','--',folder,S/'src/PawsPatchLauncher/launcher.config.json'],O/'public-client-check.log'),flush=True)
